  'work.bhagirath-homestays.s1.stat0.note': { hi: 'ऑनलाइन पहले छह महीनों में कमाया गया, ऐसी संपत्ति से जिसने कभी डिजिटल बुकिंग नहीं ली थी।', bn: 'অনলাইনে প্রথম ছয় মাসে অর্জিত, এমন একটি সম্পত্তি থেকে যা আগে কখনও ডিজিটাল বুকিং নেয়নি।', ne: 'अनलाइन पहिलो छ महिनामा कमाइएको, त्यस्तो सम्पत्तिबाट जसले कहिल्यै डिजिटल बुकिङ लिएको थिएन।' },
  'work.bhagirath-homestays.s1.stat1.label': { hi: 'बुक किए गए कमरा-रातें', bn: 'বুক করা রুম-রাত', ne: 'बुक गरिएका कोठा-रातहरू' },
  'work.bhagirath-homestays.s1.stat1.note': { hi: 'ऐसे यात्रियों द्वारा बुक की गईं जिन्होंने लिस्टिंग मिलने से पहले होमस्टे के बारे में कभी नहीं सुना था।', bn: 'এমন ভ্রমণকারীদের দ্বারা বুক করা যারা তালিকা পাওয়ার আগে হোমস্টে সম্পর্কে কখনও শোনেননি।', ne: 'सूची भेट्नुअघि होमस्टेबारे कहिल्यै नसुनेका यात्रुहरूले बुक गरेका।' },
  'work.bhagirath-homestays.s1.stat2.label': { hi: 'औसत दैनिक दर', bn: 'গড় দৈনিক হার', ne: 'औसत दैनिक दर' },
  'work.bhagirath-homestays.s1.stat2.note': { hi: 'कमरे भरने के लिए छूट देने के बजाय शांत महीनों में भी बरकरार रखी गई।', bn: 'রুম পূরণের জন্য ছাড় দেওয়ার পরিবর্তে শান্ত মাসগুলোতেও ধরে রাখা হয়েছে।', ne: 'कोठा भर्न छुट दिनुको सट्टा शान्त महिनाहरूमा पनि कायम राखिएको।' },
  'work.bhagirath-homestays.s1.stat3.label': { hi: 'शुरुआत से पहले लिस्टिंग', bn: 'শুরুর আগে তালিকা', ne: 'सुरु हुनुअघिका सूचीहरू' },
  'work.bhagirath-homestays.s1.stat3.note': { hi: 'कोई प्रोफ़ाइल नहीं, कोई तस्वीर नहीं, कोई रिव्यू नहीं, फ़ोन नंबर के बिना कमरा बुक करने का कोई तरीका नहीं।', bn: 'কোনো প্রোফাইল নেই, কোনো ছবি নেই, কোনো রিভিউ নেই, ফোন নম্বর ছাড়া রুম বুক করার কোনো উপায় নেই।', ne: 'कुनै प्रोफाइल छैन, कुनै तस्बिर छैन, कुनै समीक्षा छैन, फोन नम्बर बिना कोठा बुक गर्ने कुनै तरिका छैन।' },
  'work.bhagirath-homestays.s2.heading': { hi: 'शून्य से शुरुआत', bn: 'শূন্য থেকে শুরু', ne: 'शून्यबाट सुरुवात' },
